      $notify.success("登录成功，默认画质已设置为1080P", 4500);
      let e = JSON.parse(localStorage.getItem("setting"));
      if (e) {
        e.videoQn = "80";
        e.audioQn = "192";
        localStorage.setItem("setting", JSON.stringify(e));
      }
      this.$nextTick(() => {
        this.$store.commit("modifySetting", {
          key: "videoQn",
          value: "80"
        });
        this.$store.commit("modifySetting", {
          key: "audioQn",
          value: "192"
        });
      });
      setTimeout(() => {
        this.playFireworks();
      }, 350);
    },
    async getUserInfo() {
      try {
        const t = await At();
        let e = {
          state: false,
          uname: "",
          face: "",
          vip: false,
          coin: "",
          uid: ""
        };
        if (t.data.data.isLogin) {
          const {
            uname: i,
            face: a,
            money: s,
            vipStatus: n,
            mid: o
          } = t.data.data;
          e.state = true;
          e.uname = i;
          e.face = a + "@120w_120h_1c.avif";
          e.coin = Math.floor(s);
          e.vip = !!n;
          e.uid = o;
          this.$store.commit("updateLoginInfo", e);
          localStorage.setItem("user", JSON.stringify(e));
        } else {
          this.$store.commit("updateLoginInfo", e);
          localStorage.setItem("user", JSON.stringify(e));
        }
        const i = await lt();
        let a = i.data.data.pfs.profile.jointime;
        if (a) {
          localStorage.setItem("jointime", Le(a, true));
        }
      } catch (t) {
        $notify.error(t.message);
      }
    },
    cookieHandler(t) {
      const e = t.split("?")[1];
      if (e) {
        const t = e.split("&");
        t.forEach(t => {
          const [e, i] = t.split("=");
          this.setCookie(e, i, 30, "None");
          if (e == "DedeUserID") {
            localStorage.setItem("buid", i);
          }
        });
      }
    },
    setCookie(t, e, i, a) {
      let s = `${encodeURIComponent(t)}=${encodeURIComponent(e)}`;
      if (i) {
        const t = new Date();
        t.setDate(t.getDate() + i);
        s += `; expires=${t.toUTCString()}`;
      }
      if (a) {
        s += `; samesite=${a}`;
      }
      document.cookie = s;
    },
    clearAllCookie() {
      var t = document.cookie.match(/[^ =;]+(?=\=)/g);
      if (t) {
        for (var e = t.length; e--;) {
          document.cookie = t[e] + "=0;expires=" + new Date(0).toUTCString();
        }
      }
    },
    exitLogin() {
      Yi.send("clearCookie");
      this.clearAllCookie();
      this.isPlaySaoma = false;
      this.$store.commit("updateLoginInfo", {
        state: false,
        uname: "",
        face: "",
        vip: false,
        coin: ""
      });
      localStorage.setItem("user", JSON.stringify({
        state: false,
        uname: "",
        face: "",
        vip: false,
        coin: ""
      }));
      $notify.success("已退出登录");
      this.$store.commit("modifySetting", {
        key: "videoQn",
        value: "16"
      });
      this.$store.commit("modifySetting", {
        key: "audioQn",
        value: "64"
      });
      this.$store.commit("modifySetting", {
        key: "zimu",
        value: "false"
      });
      let t = [];
      for (let i = 0; i < localStorage.length; i++) {
        let e = localStorage.key(i);
        let a = ["setting", "defaultDownPath", "theme", "folderRenameRule", "renameRule", "createFolder", "createFolderAddIndex"];
        if (a.indexOf(e) === -1) {
          t.push(e);
        }
      }
      for (let i of t) {
        localStorage.removeItem(i);
      }
      let e = JSON.parse(localStorage.getItem("setting"));
      if (e) {
        e.videoQn = "16";
        e.audioQn = "64";
        e.zimu = "false";
        localStorage.setItem("setting", JSON.stringify(e));
      }
    },
    softDisclaimers() {
      this.$alert(ai, "声明", {
        dangerouslyUseHTMLString: true,
        showClose: false,
        confirmButtonText: "已读",
        customClass: "softDisclaimersAlert"
      });
    },
    closeSoftDisclaimersDialog() {
      try {
        MessageBox.close();
      } catch (t) {}
    }
  },
  computed: {
    ...(0, mapState)(["user", "support"])
  }
};
</script>
